/**
 * Calculate the bulk discount (2.5% extra) for lines with 10+ units, applied after line discount.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineBulkDiscount(line) {
  if (line.qty < 10) return 0;
  const afterLineDiscount = lineTotal(line) - lineDiscount(line);
  return roundCents(afterLineDiscount * 2.5 / 100);
}

/**
 * Calculate the VAT for a single line item (on the amount after both discounts).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const bulkDiscount = lineBulkDiscount(line);
  const discountedAmount = total - discount - bulkDiscount;
  return roundCents(discountedAmount * line.vatRate / 100);
}

