test('invoiceTotals VAT applied after both discounts', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 100000;
  const lineDisc = 10000;
  const afterLineDisc = 90000;
  const bulkDisc = roundCentsManual(afterLineDisc * 2.5 / 100);
  const afterBoth = afterLineDisc - bulkDisc;
  const expectedVat = roundCentsManual(afterBoth * 21 / 100);
  assert.equal(totals.vat, expectedVat);
});

