  assert(totals.discount >= lineDisc + bulkDisc - 1);
  assert(totals.discount <= lineDisc + bulkDisc + 1);
});

test('invoiceTotals bulk discount at exactly 10 units', () => {
  const at10 = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const below10 = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totalsAt = invoiceTotals(at10);
  const totalsBelow = invoiceTotals(below10);
  assert(totalsAt.discount > totalsBelow.discount);
  assert.equal(totalsBelow.discount, 0);
});

// Helper for manual calculation (banker's rounding simulation)
function roundCentsManual(x) {
  const r = Math.round(x * 1e6) / 1e6;
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

