import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for an unsent invoice', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /^DRAFT\n/);
});

test('renderInvoiceText shows the invoice number if issued', () => {
  const r1 = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const text = renderInvoiceText(r2.value);
  assert.match(text, /^INV-2026-0001\n/);
});

test('renderInvoiceText shows the customer name', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Blue Fern Bakery/);
});

test('renderInvoiceText formats a single line item', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /5 x Development \(hour\) @ €95\.00 = €475\.00/);
});

test('renderInvoiceText formats multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /5 x Development \(hour\) @ €95\.00 = €475\.00/);
  assert.match(text, /2 x Design work \(hour\) @ €85\.00 = €170\.00/);
});

test('renderInvoiceText calculates the total correctly', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // €475, VAT 21% = €99.75
      { sku: 'DES-HOUR', qty: 2 }, // €170, VAT 21% = €35.70
    ],
  });
  const text = renderInvoiceText(r.value);
  // subtotal = €645, vat = €135.45, total = €780.45
  assert.match(text, /Total: €780\.45/);
});

test('renderInvoiceText ends with the total line', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  // €95.00, VAT 21% = €19.95, total = €114.95
  assert.match(text, /Total: €114\.95\n?$/);
});

test('renderInvoiceText handles small prices correctly', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /100 x Sticker sheet @ €0\.50 = €50\.00/);
});

test('renderInvoiceText handles large prices correctly', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 2 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /2 x Brand guidelines document @ €2,450\.00 = €4,900\.00/);
  // BRAND-BOOK has 21% VAT: 4900 * 21 / 100 = 1029, total = 5929
  assert.match(text, /Total: €5,929\.00/);
});

test('renderInvoiceText shows different customer names', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text1 = renderInvoiceText(r1.value);
  const text2 = renderInvoiceText(r2.value);
  assert.match(text1, /Blue Fern Bakery/);
  assert.match(text2, /Smith, Jones & Partners/);
});

test('renderInvoiceText throws for unknown customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };
  assert.throws(() => renderInvoiceText(invoice), /Customer not found/);
});

test('renderInvoiceText produces readable multi-line output', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier (2.5% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Kite & Co');
  // DRAFT + name + 3 lines + subtotal + discount + VAT + total = 9 lines
  assert.equal(lines.length, 9);
  assert.match(lines[lines.length - 1], /^Total:/);
});

test('renderInvoiceText shows subtotal when there are lines', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Subtotal: €95\.00/);
});

test('renderInvoiceText hides discount line when discount is zero', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  const text = renderInvoiceText(r.value);
  assert.doesNotMatch(text, /Discount:/);
});

test('renderInvoiceText shows discount line when discount exists', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Discount: -€9\.50/);
});

test('renderInvoiceText formats discount with minus sign', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 1, discountPercent: 20 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Discount: -€490\.00/);
});

test('renderInvoiceText with multiple lines and mixed discounts', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
    ],
  });
  const text = renderInvoiceText(r.value);
  // DEV-HOUR: 5 * 9500 = 47500, discount 10% = 4750, discounted = 42750, VAT 21% = 8977.5 -> 8978
  // DES-HOUR: 2 * 8500 = 17000, discount 0% = 0, discounted = 17000, VAT 21% = 3570
  // subtotal = 64500, discount = 4750, vat = 12548, total = 72298
  assert.match(text, /Subtotal: €645\.00/);
  assert.match(text, /Discount: -€47\.50/);
  assert.match(text, /Total: €722\.98/);
});

test('renderInvoiceText with 100% discount line', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 100 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Subtotal: €950\.00/);
  assert.match(text, /Discount: -€950\.00/);
  assert.match(text, /Total: €0\.00/);
});

test('renderInvoiceText line count with discount', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 2, discountPercent: 15 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  // DRAFT + name + 2 line items + subtotal + discount + VAT + total = 8 lines
  assert.equal(lines.length, 8);
});

test('renderInvoiceText hides VAT line when VAT is zero', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }], // 0% VAT
  });
  const text = renderInvoiceText(r.value);
  assert.doesNotMatch(text, /VAT:/);
});

test('renderInvoiceText shows VAT line when VAT exists', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 21% VAT
  });
  const text = renderInvoiceText(r.value);
  // subtotal = 95000
  // bulk discount (2.5%) = 2375, after = 92625
  // VAT = 92625 * 21% = 19451
  assert.match(text, /VAT: €194\.51/);
});

test('renderInvoiceText shows VAT above total line', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 21% VAT
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const vatLineIndex = lines.findIndex((l) => l.startsWith('VAT:'));
  const totalLineIndex = lines.findIndex((l) => l.startsWith('Total:'));
  assert.ok(vatLineIndex !== -1, 'VAT line exists');
  assert.ok(totalLineIndex !== -1, 'Total line exists');
  assert.ok(vatLineIndex < totalLineIndex, 'VAT appears before Total');
});

test('renderInvoiceText calculates total with discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  // subtotal = 95000
  // line discount = 9500, after = 85500
  // bulk discount (2.5%) = 2137, after = 83363
  // VAT = 83363 * 21% = 17506
  // total = 95000 - (9500 + 2137) + 17506 = 100869
  assert.match(text, /Total: €1,008\.69/);
});

test('renderInvoiceText with mixed VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },      // 21% VAT, no bulk discount (qty < 10)
      { sku: 'PRINT-A4', qty: 10 },     // 9% VAT, bulk discount applies
    ],
  });
  const text = renderInvoiceText(r.value);
  // DEV-HOUR: 5 * 9500 = 47500, VAT = 9975
  // PRINT-A4: 10 * 37 = 370, bulk discount = 9, after = 361, VAT = 32
  // subtotal = 47870, discount = 9, vat = 10007, total = 57868
  assert.match(text, /Subtotal: €478\.70/);
  assert.match(text, /VAT: €100\.07/);
  assert.match(text, /Total: €578\.68/);
});

