test('lineVAT calculates VAT on discounted amount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  // lineTotal = 10000, discount = 1000, discounted = 9000
  // VAT = 9000 * 21 / 100 = 1890
  assert.equal(lineVAT(line), 1890);
});

test('lineVAT with 0% VAT rate', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT with 9% VAT rate', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 9, discountPercent: 0 };
  // lineTotal = 100000, VAT = 100000 * 9 / 100 = 9000
  assert.equal(lineVAT(line), 9000);
});

test('lineVAT with 21% VAT rate', () => {
  const line = { qty: 50, unitPrice: 500, vatRate: 21, discountPercent: 0 };
  // lineTotal = 25000, VAT = 25000 * 21 / 100 = 5250
  assert.equal(lineVAT(line), 5250);
});

test('lineVAT with discount 100%', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 100 };
  // lineTotal = 10000, discount = 10000, discounted = 0
  // VAT = 0 * 21 / 100 = 0
  assert.equal(lineVAT(line), 0);
});

test('lineVAT rounds fractional cents', () => {
  const line = { qty: 3, unitPrice: 100, vatRate: 21, discountPercent: 33 };
  // lineTotal = 300, discount = 99, discounted = 201
  // VAT = 201 * 21 / 100 = 42.21, rounded to 42
  assert.equal(lineVAT(line), 42);
});

test('invoiceTotals includes vat in returned object', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(typeof totals.vat, 'number');
  assert.equal(totals.vat, 2100);
});

test('invoiceTotals with no VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 10000);
});

test('invoiceTotals with VAT on single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 2100);
  assert.equal(totals.total, 12100);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 }, // 10000, VAT 2100
      { qty: 20, unitPrice: 500, vatRate: 9, discountPercent: 0 },   // 10000, VAT 900
      { qty: 5, unitPrice: 200, vatRate: 0, discountPercent: 0 },    // 1000, VAT 0
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 21000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 3000);
  assert.equal(totals.total, 24000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000
  // discount = 1000
  // discounted = 9000
  // vat = 9000 * 21 / 100 = 1890
  // total = 10000 - 1000 + 1890 = 10890
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals with multiple lines, discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }, // 10000 - 1000 = 9000, VAT 1890
      { qty: 5, unitPrice: 500, vatRate: 9, discountPercent: 5 },    // 2500 - 125 = 2375, VAT 213.75 -> 214
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000 + 2500 = 12500
  // discount = 1000 + 125 = 1125
  // vat = 1890 + 214 = 2104
  // total = 12500 - 1125 + 2104 = 13479
  assert.equal(totals.subtotal, 12500);
  assert.equal(totals.discount, 1125);
  assert.equal(totals.vat, 2104);
  assert.equal(totals.total, 13479);
});

test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 9500 * 10 = 95000
  });
  const totals = invoiceTotals(r.value);
  // VAT rate is 21% for DEV-HOUR
  // subtotal = 95000
  // discount = 95000 * 5 / 100 = 4750
  // discounted = 95000 - 4750 = 90250
  // vat = 90250 * 21 / 100 = 18952.5 -> 18952 (banker's rounding: 18952 is even)
  // total = 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

