test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 9500 * 10 = 95000
  });
  const totals = invoiceTotals(r.value);
  // VAT rate is 21% for DEV-HOUR
  // subtotal = 95000
  // discount = 95000 * 5 / 100 = 4750
  // discounted = 95000 - 4750 = 90250
  // vat = 90250 * 21 / 100 = 18952.5 -> 18952 (banker's rounding: 18952 is even)
  // total = 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

