  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[0].qty, 8);
});

test('addLine validates quantity', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU', () => {
