  });
  assert.equal(r1.value.lines[0].discountPercent, 5);
  assert.equal(r2.value.lines[0].discountPercent, 5);
});

test('addLine works with normalized customer ID', () => {
  const r1 = createInvoice({
    customerId: ' c-001 ',
