test('createInvoice calculates correct total with tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9 }],
  });
  const totals = invoiceTotals(r.value);
  // 9 * 9500 = 85500 subtotal
  // 85500 * 5 / 100 = 4275 discount
  // (85500 - 4275) * 21 / 100 = 81225 * 21 / 100 = 17057.25 -> 17057 VAT (banker's rounding)
  // total = 85500 - 4275 + 17057 = 98282
  assert.equal(totals.subtotal, 85500);
  assert.equal(totals.discount, 4275);
  assert.equal(totals.vat, 17057);
  assert.equal(totals.total, 98282);
});

