test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000
  // discount = 1000
  // discounted = 9000
  // vat = 9000 * 21 / 100 = 1890
  // total = 10000 - 1000 + 1890 = 10890
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals with multiple lines, discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }, // 10000 - 1000 = 9000, VAT 1890
      { qty: 5, unitPrice: 500, vatRate: 9, discountPercent: 5 },    // 2500 - 125 = 2375, VAT 213.75 -> 214
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000 + 2500 = 12500
  // discount = 1000 + 125 = 1125
  // vat = 1890 + 214 = 2104
  // total = 12500 - 1125 + 2104 = 13479
  assert.equal(totals.subtotal, 12500);
  assert.equal(totals.discount, 1125);
  assert.equal(totals.vat, 2104);
  assert.equal(totals.total, 13479);
});

test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 9500 * 10 = 95000
  });
  const totals = invoiceTotals(r.value);
  // VAT rate is 21% for DEV-HOUR
  // subtotal = 95000
  // discount = 95000 * 5 / 100 = 4750
  // discounted = 95000 - 4750 = 90250
  // vat = 90250 * 21 / 100 = 18952.5 -> 18952 (banker's rounding: 18952 is even)
  // total = 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

