    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(r1.value, { sku: 'DES-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
